package dev.eugheist.tc4modern;
import net.minecraft.world.*;import net.minecraft.world.entity.player.*;import net.minecraft.world.inventory.*;import net.minecraft.world.item.*;
public final class FocusPouchMenu extends AbstractContainerMenu {
 public final SimpleContainer contents;private final Inventory inventory;private final ItemStack pouch;private final boolean offhand;private final int held;
 public FocusPouchMenu(int id,Inventory inventory,boolean offhand){super(PechRewards.POUCH_MENU.get(),id);this.inventory=inventory;this.offhand=offhand;held=inventory.selected;pouch=offhand?inventory.player.getOffhandItem():inventory.getItem(held);contents=new SimpleContainer(18);var stored=FocusPouchItem.contents(pouch);for(int i=0;i<18;i++)contents.setItem(i,stored.get(i));contents.addListener(c->{if(!inventory.player.level().isClientSide){var list=new java.util.ArrayList<ItemStack>();for(int i=0;i<18;i++)list.add(contents.getItem(i));FocusPouchItem.store(pouch,list);inventory.setChanged();}});for(int row=0;row<3;row++)for(int col=0;col<6;col++)addSlot(new Slot(contents,row*6+col,37+18*col,51+18*row){@Override public boolean mayPlace(ItemStack stack){return stack.getItem() instanceof FociContent.Focus;}});for(int row=0;row<3;row++)for(int col=0;col<9;col++)addSlot(new Slot(inventory,9+row*9+col,8+18*col,151+18*row));for(int col=0;col<9;col++){int inventoryIndex=col;addSlot(new Slot(inventory,col,8+18*col,209){@Override public boolean mayPickup(Player p){return offhand||inventoryIndex!=held;}@Override public boolean mayPlace(ItemStack stack){return offhand||inventoryIndex!=held;}});}}
 @Override public boolean stillValid(Player player){return !pouch.isEmpty()&&pouch.getItem() instanceof FocusPouchItem&&(offhand?player.getOffhandItem():inventory.getItem(held))==pouch;}
 @Override public void clicked(int slot,int button,ClickType type,Player player){if(!offhand&&type==ClickType.SWAP&&button==held)return;super.clicked(slot,button,type,player);}
 @Override public ItemStack quickMoveStack(Player player,int index){var slot=slots.get(index);if(!slot.mayPickup(player))return ItemStack.EMPTY;var stack=slot.getItem();var original=stack.copy();if(index<18){if(!moveItemStackTo(stack,18,54,true))return ItemStack.EMPTY;}else if(stack.getItem() instanceof FociContent.Focus){if(!moveItemStackTo(stack,0,18,false))return ItemStack.EMPTY;}else return ItemStack.EMPTY;if(stack.isEmpty())slot.setByPlayer(ItemStack.EMPTY);else slot.setChanged();return original;}
}
